1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.sql.PreparedStatement;
6	import java.sql.Statement;
7	import java.sql.Timestamp;
8	import java.time.Clock;
9	import java.time.Instant;
10	import java.util.ArrayList;
11	import java.util.LinkedHashMap;
12	import java.util.LinkedHashSet;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.Set;
16	
17	import org.springframework.dao.DuplicateKeyException;
18	import org.springframework.http.HttpStatus;
19	import org.springframework.jdbc.core.JdbcTemplate;
20	import org.springframework.jdbc.support.GeneratedKeyHolder;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	import com.example.starter.api.dto.ColorCheckRequest;
25	import com.example.starter.api.dto.CreateRecipeRequest;
26	import com.example.starter.api.dto.FeedRequest;
27	import com.example.starter.api.dto.JudgeRequest;
28	import com.example.starter.api.dto.LateColorRequest;
29	import com.example.starter.api.dto.MergeLotsRequest;
30	import com.example.starter.api.dto.RecipeItemInput;
31	import com.example.starter.api.dto.ScheduleLotRequest;
32	import com.example.starter.api.dto.WeighingInput;
33	import com.example.starter.domain.LotStatus;
34	import com.example.starter.domain.RecipeStatus;
35	import com.example.starter.domain.Verdict;
36	import com.example.starter.support.ApiException;
37	
38	/**
39	 * 印染配方放大与缸差控制核心服务。
40	 * 阈值：对色 ΔE&lt;=0.8 放行；称量偏差绝对值&lt;=0.5% 合法；缸差&gt;0.5 须回修且仅一次。
41	 */
42	@Service
43	public class DyeService {
44	
45	    /** 对色放行阈值（含边界，恰 0.8 合格）。 */
46	    static final BigDecimal COLOR_LIMIT = new BigDecimal("0.8");
47	    /** 称量偏差允许上限百分比（含边界，恰 0.5% 合法）。 */
48	    static final BigDecimal WEIGH_LIMIT_PCT = new BigDecimal("0.5");
49	    /** 缸差阈值：超过 0.5 须回修。 */
50	    static final BigDecimal LOT_DIFF_LIMIT = new BigDecimal("0.5");
51	    private static final int DEVIATION_SCALE = 6;
52	
53	    private final JdbcTemplate jdbc;
54	    private final IdempotencyService idempotency;
55	    private final Clock clock;
56	
57	    public DyeService(JdbcTemplate jdbc, IdempotencyService idempotency, Clock clock) {
58	        this.jdbc = jdbc;
59	        this.idempotency = idempotency;
60	        this.clock = clock;
61	    }
62	
63	    private Timestamp nowTs() {
64	        return Timestamp.from(Instant.now(clock));
65	    }
66	
67	    // ---------------------------------------------------------------------
68	    // 配方：草稿 → 发布冻结；修改已发布配方生成新版本并保留旧版本
69	    // ---------------------------------------------------------------------
70	
71	    @Transactional
72	    public ServiceResult createRecipe(CreateRecipeRequest req) {
73	        Integer exists = jdbc.query("SELECT 1 FROM recipe WHERE recipe_code = ?",
74	                rs -> rs.next() ? 1 : null, req.recipeCode());
75	        if (exists != null) {
76	            throw new ApiException(HttpStatus.CONFLICT,
77	                    "配方编码 " + req.recipeCode() + " 已存在；修改已发布配方须生成新版本");
78	        }
79	        validateItems(req.items());
80	        Timestamp now = nowTs();
81	        jdbc.update("INSERT INTO recipe (recipe_code, version, liquor_ratio, status, created_at) "
82	                + "VALUES (?, 1, ?, ?, ?)",
83	                req.recipeCode(), req.liquorRatio(), RecipeStatus.DRAFT.name(), now);
84	        Long recipeId = jdbc.queryForObject(
85	                "SELECT id FROM recipe WHERE recipe_code = ? AND version = 1", Long.class, req.recipeCode());
86	        insertItems(recipeId, req.items());
87	        return ServiceResult.created(recipeView(req.recipeCode(), 1));
88	    }
89	
90	    @Transactional
91	    public ServiceResult publishRecipe(String recipeCode) {
92	        Map<String, Object> latest = latestRecipe(recipeCode);
93	        if (RecipeStatus.PUBLISHED.name().equals(latest.get("status"))) {
94	            throw new ApiException(HttpStatus.CONFLICT,
95	                    "配方 " + recipeCode + " v" + latest.get("version") + " 已发布冻结，不能重复发布或修改");
96	        }
97	        jdbc.update("UPDATE recipe SET status = ? WHERE id = ?",
98	                RecipeStatus.PUBLISHED.name(), latest.get("id"));
99	        return ServiceResult.ok(recipeView(recipeCode, (Integer) latest.get("version")));
100	    }
101	
102	    /**
103	     * 修改已发布配方：复制为下一草稿版本，旧版本原样保留。
104	     */
105	    @Transactional
106	    public ServiceResult reviseRecipe(String recipeCode, CreateRecipeRequest req) {
107	        Map<String, Object> latest = latestRecipe(recipeCode);
108	        if (!RecipeStatus.PUBLISHED.name().equals(latest.get("status"))) {
109	            throw new ApiException(HttpStatus.CONFLICT,
110	                    "仅已发布冻结版本才能通过修订生成新版本；当前 v" + latest.get("version") + " 为草稿");
111	        }
112	        validateItems(req.items());
113	        int newVersion = (Integer) latest.get("version") + 1;
114	        Timestamp now = nowTs();
115	        jdbc.update("INSERT INTO recipe (recipe_code, version, liquor_ratio, status, created_at) "
116	                + "VALUES (?, ?, ?, ?, ?)",
117	                recipeCode, newVersion, req.liquorRatio(), RecipeStatus.DRAFT.name(), now);
118	        Long recipeId = jdbc.queryForObject(
119	                "SELECT id FROM recipe WHERE recipe_code = ? AND version = ?",
120	                Long.class, recipeCode, newVersion);
121	        insertItems(recipeId, req.items());
122	        return ServiceResult.created(recipeView(recipeCode, newVersion));
123	    }
124	
125	    // ---------------------------------------------------------------------
126	    // 打小样对色
127	    // ---------------------------------------------------------------------
128	
129	    @Transactional
130	    public ServiceResult colorCheck(ColorCheckRequest req) {
131	        Map<String, Object> payload = new LinkedHashMap<>();
132	        payload.put("sampleId", req.sampleId());
133	        payload.put("deltaE", req.deltaE());
134	        return idempotency.execute(req.requestId(), "COLOR_CHECK", payload, () -> {
135	            boolean passed = req.deltaE().compareTo(COLOR_LIMIT) <= 0;
136	            jdbc.update("INSERT INTO color_check (request_id, sample_id, delta_e, passed, created_at) "
137	                    + "VALUES (?, ?, ?, ?, ?)",
138	                    req.requestId(), req.sampleId(), req.deltaE(), passed, nowTs());
139	            Map<String, Object> body = new LinkedHashMap<>();
140	            body.put("requestId", req.requestId());
141	            body.put("sampleId", req.sampleId());
142	            body.put("deltaE", req.deltaE());
143	            body.put("limit", COLOR_LIMIT);
144	            body.put("passed", passed);
145	            body.put("decision", passed ? "放行" : "不放行");
146	            return ServiceResult.ok(body);
147	        });
148	    }
149	
150	    // ---------------------------------------------------------------------
151	    // 排缸：冻结配方版本 + 染缸唯一占用（并发唯一受理）
152	    // ---------------------------------------------------------------------
153	
154	    @Transactional
155	    public ServiceResult scheduleLot(ScheduleLotRequest req) {
156	        Map<String, Object> payload = new LinkedHashMap<>();
157	        payload.put("lotNo", req.lotNo());
158	        payload.put("vatNo", req.vatNo());
159	        payload.put("recipeCode", req.recipeCode());
160	        payload.put("recipeVersion", req.recipeVersion());
161	        payload.put("fabricWeightKg", req.fabricWeightKg());
162	        return idempotency.execute(req.requestId(), "SCHEDULE", payload, () -> {
163	            Map<String, Object> recipe = requirePublishedRecipe(req.recipeCode(), req.recipeVersion());
164	            Timestamp now = nowTs();
165	            Long lotId;
166	            try {
167	                jdbc.update("INSERT INTO lot (lot_no, vat_no, recipe_code, recipe_version, liquor_ratio, "
168	                        + "fabric_weight_kg, status, repair_count, created_at, updated_at) "
169	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?)",
170	                        req.lotNo(), req.vatNo(), req.recipeCode(), req.recipeVersion(),
171	                        recipe.get("liquor_ratio"), req.fabricWeightKg(), LotStatus.CREATED.name(), now, now);
172	                lotId = jdbc.queryForObject("SELECT id FROM lot WHERE lot_no = ?", Long.class, req.lotNo());
173	            } catch (DuplicateKeyException dupLot) {
174	                throw new ApiException(HttpStatus.CONFLICT, "缸次号 " + req.lotNo() + " 已存在");
175	            }
176	            try {
177	                // 行存在即占用：主键冲突保证同一染缸同时刻只有一个执行中缸次，并发排缸唯一受理。
178	                jdbc.update("INSERT INTO vat_active (vat_no, lot_id, since) VALUES (?, ?, ?)",
179	                        req.vatNo(), lotId, now);
180	            } catch (DuplicateKeyException dupVat) {
181	                throw new ApiException(HttpStatus.CONFLICT,
182	                        "染缸 " + req.vatNo() + " 已有执行中缸次，并发排缸唯一受理");
183	            }
184	            return ServiceResult.created(lotView(req.lotNo()));
185	        });
186	    }
187	
188	    // ---------------------------------------------------------------------
189	    // 并缸：须同配方（同编码同冻结版本）同浴比
190	    // ---------------------------------------------------------------------
191	
192	    @Transactional
193	    public ServiceResult mergeLots(MergeLotsRequest req) {
194	        Map<String, Object> payload = new LinkedHashMap<>();
195	        payload.put("lotNo", req.lotNo());
196	        payload.put("targetLotNo", req.targetLotNo());
197	        return idempotency.execute(req.requestId(), "MERGE", payload, () -> {
198	            if (req.lotNo().equals(req.targetLotNo())) {
199	                throw new ApiException(HttpStatus.BAD_REQUEST, "缸次不能与自身并缸");
200	            }
201	            Map<String, Object> source = requireLot(req.lotNo());
202	            Map<String, Object> target = requireLot(req.targetLotNo());
203	            requireStatus(source, LotStatus.CREATED);
204	            requireStatus(target, LotStatus.CREATED);
205	            if (!source.get("recipe_code").equals(target.get("recipe_code"))
206	                    || ((Number) source.get("recipe_version")).intValue()
207	                        != ((Number) target.get("recipe_version")).intValue()) {
208	                throw new ApiException(HttpStatus.CONFLICT,
209	                        "不同配方拒绝并缸：" + source.get("recipe_code") + " v" + source.get("recipe_version")
210	                                + " 与 " + target.get("recipe_code") + " v" + target.get("recipe_version"));
211	            }
212	            if (((BigDecimal) source.get("liquor_ratio")).compareTo((BigDecimal) target.get("liquor_ratio")) != 0) {
213	                throw new ApiException(HttpStatus.CONFLICT, "浴比不同拒绝并缸");
214	            }
215	            Timestamp now = nowTs();
216	            BigDecimal combinedWeight = ((BigDecimal) source.get("fabric_weight_kg"))
217	                    .add((BigDecimal) target.get("fabric_weight_kg"));
218	            jdbc.update("UPDATE lot SET merged_into_lot_id = ?, status = ?, updated_at = ? WHERE id = ?",
219	                    target.get("id"), LotStatus.MERGED.name(), now, source.get("id"));
220	            jdbc.update("UPDATE lot SET fabric_weight_kg = ?, updated_at = ? WHERE id = ?",
221	                    combinedWeight, now, target.get("id"));
222	            // 被并缸次释放原染缸占用，织物并入目标缸同缸生产。
223	            jdbc.update("DELETE FROM vat_active WHERE vat_no = ? AND lot_id = ?",
224	                    source.get("vat_no"), source.get("id"));
225	
226	            Map<String, Object> body = new LinkedHashMap<>();
227	            body.put("requestId", req.requestId());
228	            body.put("mergedLotNo", req.lotNo());
229	            body.put("targetLotNo", req.targetLotNo());
230	            body.put("combinedFabricWeightKg", combinedWeight);
231	            body.put("status", LotStatus.MERGED.name());
232	            return ServiceResult.ok(body);
233	        });
234	    }
235	
236	    // ---------------------------------------------------------------------
237	    // 投料：放大换算 → 偏差校验 → 称量记录与库存扣减同一事务原子完成
238	    // ---------------------------------------------------------------------
239	
240	    @Transactional
241	    public ServiceResult feed(FeedRequest req) {
242	        Map<String, Object> payload = new LinkedHashMap<>();
243	        payload.put("lotNo", req.lotNo());
244	        List<Map<String, Object>> weighingPayload = new ArrayList<>();
245	        for (WeighingInput w : req.weighings()) {
246	            Map<String, Object> entry = new LinkedHashMap<>();
247	            entry.put("dyeCode", w.dyeCode());
248	            entry.put("actualG", w.actualG());
249	            weighingPayload.add(entry);
250	        }
251	        weighingPayload.sort((a, b) -> String.valueOf(a.get("dyeCode")).compareTo(String.valueOf(b.get("dyeCode"))));
252	        payload.put("weighings", weighingPayload);
253	
254	        return idempotency.execute(req.requestId(), "FEED", payload, () -> {
255	            Map<String, Object> lot = requireLot(req.lotNo());
256	            requireStatus(lot, LotStatus.CREATED);
257	
258	            Long versionRecipeId = recipeId((String) lot.get("recipe_code"),
259	                    ((Number) lot.get("recipe_version")).intValue());
260	            List<Map<String, Object>> items = recipeItems(versionRecipeId);
261	            BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
262	            BigDecimal fabricKg = (BigDecimal) lot.get("fabric_weight_kg");
263	
264	            Map<String, BigDecimal> actualByDye = new LinkedHashMap<>();
265	            for (WeighingInput w : req.weighings()) {
266	                if (actualByDye.put(w.dyeCode(), w.actualG()) != null) {
267	                    throw new ApiException(HttpStatus.BAD_REQUEST,
268	                            "染化料 " + w.dyeCode() + " 称量记录重复");
269	                }
270	            }
271	            Set<String> required = new LinkedHashSet<>();
272	            List<Map<String, Object>> computed = new ArrayList<>();
273	            for (Map<String, Object> item : items) {
274	                String dyeCode = (String) item.get("dye_code");
275	                BigDecimal dosage = (BigDecimal) item.get("dosage_gpl");
276	                required.add(dyeCode);
277	                BigDecimal target = dosage.multiply(ratio).multiply(fabricKg).setScale(4, RoundingMode.HALF_UP);
278	                BigDecimal actual = actualByDye.get(dyeCode);
279	                if (actual == null) {
280	                    throw new ApiException(HttpStatus.BAD_REQUEST,
281	                            "缺少染化料 " + dyeCode + " 的实际称量，拒绝投料");
282	                }
283	                BigDecimal deviation = actual.subtract(target)
284	                        .multiply(BigDecimal.valueOf(100))
285	                        .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
286	                if (deviation.abs().compareTo(WEIGH_LIMIT_PCT) > 0) {
287	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
288	                            "染化料 " + dyeCode + " 称量偏差 " + deviation + "% 超过 ±0.5%（恰 0.5% 合法），整单拒绝投料且不扣库存");
289	                }
290	                Map<String, Object> row = new LinkedHashMap<>();
291	                row.put("dyeCode", dyeCode);
292	                row.put("targetG", target);
293	                row.put("actualG", actual);
294	                row.put("deviationPct", deviation);
295	                computed.add(row);
296	            }
297	            if (!actualByDye.keySet().equals(required)) {
298	                Set<String> extra = new LinkedHashSet<>(actualByDye.keySet());
299	                extra.removeAll(required);
300	                throw new ApiException(HttpStatus.BAD_REQUEST,
301	                        "存在配方外染化料称量：" + extra + "，拒绝投料");
302	            }
303	
304	            // 库存预检：任一染化料不足整单回滚，杜绝部分扣减。
305	            for (Map<String, Object> row : computed) {
306	                BigDecimal stock = jdbc.queryForObject("SELECT stock_g FROM dye WHERE code = ?",
307	                        BigDecimal.class, row.get("dyeCode"));
308	                if (stock == null) {
309	                    throw new ApiException(HttpStatus.BAD_REQUEST,
310	                            "染化料 " + row.get("dyeCode") + " 不存在，拒绝投料");
311	                }
312	                if (stock.compareTo((BigDecimal) row.get("actualG")) < 0) {
313	                    throw new ApiException(HttpStatus.CONFLICT,
314	                            "染化料 " + row.get("dyeCode") + " 库存不足，拒绝投料且不扣库存");
315	                }
316	            }
317	
318	            Timestamp now = nowTs();
319	            jdbc.update("INSERT INTO feeding (request_id, lot_id, fed_at) VALUES (?, ?, ?)",
320	                    req.requestId(), lot.get("id"), now);
321	            Long feedingId = jdbc.queryForObject(
322	                    "SELECT id FROM feeding WHERE request_id = ?", Long.class, req.requestId());
323	            for (Map<String, Object> row : computed) {
324	                jdbc.update("INSERT INTO weighing (feeding_id, dye_code, target_g, actual_g, deviation_pct) "
325	                        + "VALUES (?, ?, ?, ?, ?)",
326	                        feedingId, row.get("dyeCode"), row.get("targetG"), row.get("actualG"),
327	                        row.get("deviationPct"));
328	                int deducted = jdbc.update("UPDATE dye SET stock_g = stock_g - ? WHERE code = ? AND stock_g >= ?",
329	                        row.get("actualG"), row.get("dyeCode"), row.get("actualG"));
330	                if (deducted != 1) {
331	                    // 并发扣减防护：与预检构成双保险，失败随事务整体回滚。
332	                    throw new ApiException(HttpStatus.CONFLICT,
333	                            "染化料 " + row.get("dyeCode") + " 并发扣减失败，整单回滚");
334	                }
335	            }
336	            jdbc.update("UPDATE lot SET status = ?, updated_at = ? WHERE id = ?",
337	                    LotStatus.FED.name(), now, lot.get("id"));
338	
339	            Map<String, Object> body = new LinkedHashMap<>();
340	            body.put("requestId", req.requestId());
341	            body.put("lotNo", req.lotNo());
342	            body.put("liquorRatio", ratio);
343	            body.put("fabricWeightKg", fabricKg);
344	            body.put("weighings", computed);
345	            body.put("status", LotStatus.FED.name());
346	            body.put("fedAt", now.toInstant().toString());
347	            return ServiceResult.ok(body);
348	        });
349	    }
350	
351	    // ---------------------------------------------------------------------
352	    // 出缸判定：同配方缸差 > 0.5 回修一次，回修后仍超差降级
353	    // ---------------------------------------------------------------------
354	
355	    @Transactional
356	    public ServiceResult judge(JudgeRequest req) {
357	        Map<String, Object> payload = new LinkedHashMap<>();
358	        payload.put("lotNo", req.lotNo());
359	        payload.put("deltaE", req.deltaE());
360	        payload.put("referenceLotNo", req.referenceLotNo() == null ? "" : req.referenceLotNo());
361	        return idempotency.execute(req.requestId(), "JUDGE", payload, () -> {
362	            Map<String, Object> lot = requireLot(req.lotNo());
363	            String status = (String) lot.get("status");
364	            int round;
365	            if (LotStatus.FED.name().equals(status)) {
366	                round = 0;
367	            } else if (LotStatus.REPAIRING.name().equals(status)) {
368	                round = ((Number) lot.get("repair_count")).intValue();
369	            } else {
370	                throw new ApiException(HttpStatus.CONFLICT,
371	                        "缸次 " + req.lotNo() + " 当前状态 " + status + "，不允许出缸判定（须已投料或回修中）");
372	            }
373	
374	            Map<String, Object> reference = null;
375	            if (req.referenceLotNo() != null && !req.referenceLotNo().isBlank()) {
376	                reference = requireLot(req.referenceLotNo());
377	                if (!reference.get("recipe_code").equals(lot.get("recipe_code"))
378	                        || ((Number) reference.get("recipe_version")).intValue()
379	                        != ((Number) lot.get("recipe_version")).intValue()) {
380	                    throw new ApiException(HttpStatus.BAD_REQUEST, "对比缸必须同配方同冻结版本");
381	                }
382	            } else {
383	                reference = latestJudgedSibling(lot);
384	            }
385	
386	            BigDecimal refDelta = null;
387	            BigDecimal diff = null;
388	            if (reference != null) {
389	                refDelta = latestDelta((Long) reference.get("id"));
390	                if (refDelta == null) {
391	                    throw new ApiException(HttpStatus.BAD_REQUEST,
392	                            "对比缸 " + reference.get("lot_no") + " 尚无出缸测色记录，无法计算缸差");
393	                }
394	                diff = req.deltaE().subtract(refDelta).abs().setScale(4, RoundingMode.HALF_UP);
395	            }
396	
397	            Verdict verdict;
398	            LotStatus nextStatus;
399	            boolean over = diff != null && diff.compareTo(LOT_DIFF_LIMIT) > 0;
400	            if (!over) {
401	                verdict = Verdict.PASS;
402	                nextStatus = LotStatus.PASSED;
403	            } else if (round == 0) {
404	                verdict = Verdict.REPAIR;
405	                nextStatus = LotStatus.REPAIRING;
406	            } else {
407	                verdict = Verdict.DOWNGRADE;
408	                nextStatus = LotStatus.DOWNGRADED;
409	            }
410	
411	            Timestamp now = nowTs();
412	            jdbc.update("INSERT INTO lot_judgment (request_id, lot_id, round, delta_e, reference_lot_id, "
413	                    + "reference_delta_e, diff, verdict, judged_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
414	                    req.requestId(), lot.get("id"), round, req.deltaE(),
415	                    reference == null ? null : reference.get("id"), refDelta, diff, verdict.name(), now);
416	            int newRepairCount = ((Number) lot.get("repair_count")).intValue()
417	                    + (verdict == Verdict.REPAIR ? 1 : 0);
418	            jdbc.update("UPDATE lot SET status = ?, repair_count = ?, updated_at = ? WHERE id = ?",
419	                    nextStatus.name(), newRepairCount, now, lot.get("id"));
420	
421	            Map<String, Object> body = new LinkedHashMap<>();
422	            body.put("requestId", req.requestId());
423	            body.put("lotNo", req.lotNo());
424	            body.put("round", round);
425	            body.put("deltaE", req.deltaE());
426	            body.put("referenceLotNo", reference == null ? null : reference.get("lot_no"));
427	            body.put("referenceDeltaE", refDelta);
428	            body.put("diff", diff);
429	            body.put("limit", LOT_DIFF_LIMIT);
430	            body.put("verdict", verdict.name());
431	            body.put("status", nextStatus.name());
432	            body.put("repairCount", newRepairCount);
433	            body.put("note", verdictNote(verdict));
434	            return ServiceResult.ok(body);
435	        });
436	    }
