442	    @Transactional
443	    public ServiceResult archiveLot(String lotNo) {
444	        Map<String, Object> lot = requireLot(lotNo);
445	        String status = (String) lot.get("status");
446	        boolean replayed = LotStatus.ARCHIVED.name().equals(status);
447	        if (!replayed) {
448	            if (LotStatus.CREATED.name().equals(status) || LotStatus.FED.name().equals(status)
449	                    || LotStatus.REPAIRING.name().equals(status) || LotStatus.MERGED.name().equals(status)) {
450	                throw new ApiException(HttpStatus.CONFLICT,
451	                        "缸次 " + lotNo + " 状态 " + status + "，未出缸判定不得归档");
452	            }
453	            Timestamp now = nowTs();
454	            jdbc.update("UPDATE lot SET status = ?, updated_at = ? WHERE id = ?",
455	                    LotStatus.ARCHIVED.name(), now, lot.get("id"));
456	            jdbc.update("DELETE FROM vat_active WHERE lot_id = ?", lot.get("id"));
457	        }
458	        Map<String, Object> body = new LinkedHashMap<>();
459	        body.put("lotNo", lotNo);
460	        body.put("status", LotStatus.ARCHIVED.name());
461	        body.put("terminal", true);
462	        body.put("replayed", replayed);
463	        return ServiceResult.ok(body);
