471	        GeneratedKeyHolder keyHolder = new GeneratedKeyHolder();
472	        jdbc.update(con -> {
473	            PreparedStatement ps = con.prepareStatement(
474	                    "INSERT INTO late_color_event (lot_id, delta_e, note, received_at) VALUES (?, ?, ?, ?)",
475	                    Statement.RETURN_GENERATED_KEYS);
