477	            ps.setBigDecimal(2, req.deltaE());
478	            ps.setString(3, req.note());
479	            ps.setTimestamp(4, now);
480	            return ps;
481	        }, keyHolder);
482	        Map<String, Object> body = new LinkedHashMap<>();
483	        body.put("eventId", keyHolder.getKey());
484	        body.put("lotNo", lotNo);
485	        body.put("deltaE", req.deltaE());
486	        body.put("archived", archived);
487	        body.put("recordedOnly", archived);
