726	        view.put("status", lot.get("status"));
727	        view.put("repairCount", lot.get("repair_count"));
728	        view.put("createdAt", ((Timestamp) lot.get("created_at")).toInstant().toString());
729	        view.put("updatedAt", ((Timestamp) lot.get("updated_at")).toInstant().toString());
730	
731	        Long feedingId = jdbc.query("SELECT id FROM feeding WHERE lot_id = ? ORDER BY id DESC LIMIT 1",
732	                rs -> rs.next() ? rs.getLong(1) : null, lot.get("id"));
733	        if (feedingId != null) {
734	            List<Map<String, Object>> weighings = new ArrayList<>();
735	            jdbc.query("SELECT dye_code, target_g, actual_g, deviation_pct FROM weighing "
736	                    + "WHERE feeding_id = ? ORDER BY id", rs -> {
737	                Map<String, Object> w = new LinkedHashMap<>();
738	                w.put("dyeCode", rs.getString("dye_code"));
739	                w.put("targetG", rs.getBigDecimal("target_g"));
740	                w.put("actualG", rs.getBigDecimal("actual_g"));
741	                w.put("deviationPct", rs.getBigDecimal("deviation_pct"));
742	                weighings.add(w);
743	            }, feedingId);
744	            view.put("weighings", weighings);
745	        }
746	        List<Map<String, Object>> judgments = new ArrayList<>();
747	        jdbc.query("SELECT round, delta_e, reference_lot_id, reference_delta_e, diff, verdict, judged_at "
748	                + "FROM lot_judgment WHERE lot_id = ? ORDER BY id", rs -> {
749	            Map<String, Object> j = new LinkedHashMap<>();
750	            j.put("round", rs.getInt("round"));
751	            j.put("deltaE", rs.getBigDecimal("delta_e"));
752	            j.put("referenceLotId", rs.getObject("reference_lot_id"));
753	            j.put("referenceDeltaE", rs.getBigDecimal("reference_delta_e"));
754	            j.put("diff", rs.getBigDecimal("diff"));
755	            j.put("verdict", rs.getString("verdict"));
756	            j.put("judgedAt", rs.getTimestamp("judged_at").toInstant().toString());
757	            judgments.add(j);
758	        }, lot.get("id"));
759	        view.put("judgments", judgments);
760	        return view;
761	    }
