38	    /** 创建配方草稿（v1）。 */
39	    @PostMapping("/recipes")
40	    public ResponseEntity<Map<String, Object>> createRecipe(@Valid @RequestBody CreateRecipeRequest req) {
41	        return toResponse(dyeService.createRecipe(req));
