55	    }
56	
57	    /** 打小样对色（requestId 幂等）。 */
58	    @PostMapping("/color-checks")
59	    public ResponseEntity<Map<String, Object>> colorCheck(@Valid @RequestBody ColorCheckRequest req) {
60	        return toResponse(dyeService.colorCheck(req));
61	    }
62	
63	    /** 排缸：占用染缸、绑定冻结配方版本（requestId 幂等，并发唯一受理）。 */
64	    @PostMapping("/lots")
