72	        return toResponse(dyeService.mergeLots(req));
73	    }
74	
75	    /** 投料：称量偏差校验与库存扣减同事务原子完成（requestId 幂等）。 */
76	    @PostMapping("/feedings")
77	    public ResponseEntity<Map<String, Object>> feed(@Valid @RequestBody FeedRequest req) {
78	        return toResponse(dyeService.feed(req));
79	    }
80	
81	    /** 出缸判定：缸差台账、回修一次、降级（requestId 幂等）。 */
82	    @PostMapping("/judgments")
83	    public ResponseEntity<Map<String, Object>> judge(@Valid @RequestBody JudgeRequest req) {
84	        return toResponse(dyeService.judge(req));
85	    }
86	
87	    /** 判定归档：终态，重复归档幂等成功。 */
88	    @PostMapping("/lots/{lotNo}/archive")
89	    public ResponseEntity<Map<String, Object>> archiveLot(@PathVariable String lotNo) {
90	        return toResponse(dyeService.archiveLot(lotNo));
91	    }
92	
93	    /** 归档后迟到测色：只登记迟到事件。 */
94	    @PostMapping("/lots/{lotNo}/late-color")
95	    public ResponseEntity<Map<String, Object>> receiveLateColor(@PathVariable String lotNo,
96	                                                                @Valid @RequestBody LateColorRequest req) {
97	        return toResponse(dyeService.receiveLateColor(lotNo, req));
98	    }
99	
100	    @GetMapping("/lots/{lotNo}")
101	    public ResponseEntity<Map<String, Object>> getLot(@PathVariable String lotNo) {
102	        return toResponse(dyeService.getLot(lotNo));
103	    }
104	
105	    /** 复算配方版本、称量链与缸差台账。 */
106	    @GetMapping("/recipes/{recipeCode}/recalculate")
107	    public ResponseEntity<Map<String, Object>> recalculate(@PathVariable String recipeCode) {
108	        return toResponse(dyeService.recalculate(recipeCode));
109	    }
110	
111	    private ResponseEntity<Map<String, Object>> toResponse(ServiceResult result) {
112	        return ResponseEntity.status(result.status())
113	                .header("X-Idempotent-Replayed", String.valueOf(result.replayed()))
114	                .body(result.body());
115	    }
116	}
