3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	
6	import java.math.BigDecimal;
7	import java.util.ArrayList;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.concurrent.CountDownLatch;
11	import java.util.concurrent.ExecutorService;
12	import java.util.concurrent.Executors;
13	import java.util.concurrent.Future;
14	import java.util.concurrent.TimeUnit;
15	
16	import org.junit.jupiter.api.Test;
17	import org.springframework.http.ResponseEntity;
18	
19	/**
20	 * 并发/幂等边界（真实多线程 + CountDownLatch 同时发起，结果与最终数据双断言）：
21	 * 1) 同一染缸并发排缸唯一受理；
22	 * 2) 同一 requestId 并发同参投料只生效一次（其余重放）；
23	 * 3) 库存只够一单时，并并发投料恰成功一单，无超扣/部分扣减。
24	 */
25	class DyeConcurrencyTest extends BaseIntegrationTest {
26	
27	    private static final int THREADS = 8;
28	
29	    @Test
30	    void concurrentSchedule_sameVat_onlyOneAccepted() throws Exception {
31	        ExecutorService pool = Executors.newFixedThreadPool(THREADS);
32	        CountDownLatch ready = new CountDownLatch(THREADS);
33	        CountDownLatch start = new CountDownLatch(1);
34	        List<Future<Integer>> results = new ArrayList<>();
35	
36	        for (int i = 0; i < THREADS; i++) {
37	            final int idx = i;
38	            results.add(pool.submit(() -> {
39	                ready.countDown();
40	                start.await();
41	                ResponseEntity<Map> resp = post("/api/lots", Map.of(
42	                        "requestId", "cs-vat-" + idx,
43	                        "lotNo", "LC-" + idx,
44	                        "vatNo", "VAT-SHARED",
45	                        "recipeCode", "R-BASE",
46	                        "recipeVersion", 1,
47	                        "fabricWeightKg", new BigDecimal("50")));
48	                return resp.getStatusCode().value();
49	            }));
50	        }
51	
52	        assertTrue(ready.await(10, TimeUnit.SECONDS));
53	        start.countDown();
54	
55	        long created = 0;
56	        long conflict = 0;
57	        for (Future<Integer> f : results) {
58	            int code = f.get(30, TimeUnit.SECONDS);
59	            if (code == 201) {
