    @Test
    void feed_firstAttemptRollsBack_sameKeyCanRetryWithCorrectParams() {
        schedule("ie-sched-2", "LE2", "VE2", "R-BASE", 1, "50");
        BigDecimal redBefore = stock("D-RED");

        // 首次偏差超标：业务异常导致事务（含幂等占位行）整体回滚
